    switch (tool.integration) {
      case 'file':
        return _executeFileTool(toolName, args);
      case 'cli':
        return _executeCliTool(toolName, args);
      default:
        return _err('Unsupported non-HTTP integration: ${tool.integration}');
    }
  }

