  /// vendor detection when routing `tracker_*` aliases.
  String? _extractKeyHint(Map<String, dynamic> args) {
    for (final field in const [
      'key',
      'ticketKey',
      'ticket',
      'issueKey',
      'id'
    ]) {
      final value = args[field];
      if (value != null) return value.toString();
