List<ToolDefinition> defaultToolCatalog() => [
      ...jiraTools(),
      ...githubTools(),
      ...gitlabTools(),
      ...confluenceTools(),
      ...aiTools(),
      ...fileTools(),
      ...cliTools(),
      ...adoTools(),
      ...testrailTools(),
      ...bitriseTools(),
