/// Java `JsEnvPolicyTest` parity: one secret-aware policy for env_get/env_list.
void main() {
  group('looksSecret', () {
    test('credential names are secret', () {
      for (final name in [
        'JIRA_API_TOKEN',
        'ADO_PAT_TOKEN',
        'GH_TOKEN',
        'SOURCE_GITHUB_TOKEN',
        'OPENAI_API_KEY',
        'XRAY_CLIENT_SECRET',
