      for (final name in PropertyNames.all) {
        if (JsEnvPolicy.looksSecret(name)) {
          expect(JsEnvPolicy.defaultAllowed, isNot(contains(name)));
        } else {
          expect(JsEnvPolicy.defaultAllowed, contains(name), reason: name);
        }
