{"path":"/home/runner/work/dmtools-dart/dmtools-dart/lib/src/env/js_env_policy.dart","content":"/// Single source of truth for WHICH configuration values a JS agent may read.
///
/// Dart port of Java `com.github.istin.dmtools.env.JsEnvPolicy` (dm.ai#710),
/// the spec for the `env_get` / `env_list` tools. Rules, in order:
///
/// 1. A name that looks like a secret is NEVER readable, whatever any
///    allowlist says (whole `_`-separated word match; `*_MAX_TOKENS` and
///    `*_TOKEN_LIMIT` stay readable).
/// 2. The default allowlist is every name the reader declares
///    ([PropertyNames.all]) minus the secrets.
/// 3. `JS_ENV_ALLOWLIST=A,B` extends it; secret-looking entries are dropped.
library;

import '../config/property_names.dart';

/// Outcome of [JsEnvPolicy.decide].
enum EnvDecision {
  /// Readable through `env_get`.
  allowed,

  /// Looks like a credential: never readable.
  secret,

  /// Well-formed, but neither built in nor added via `JS_ENV_ALLOWLIST`.
  notAllowlisted,

  /// Not a `[A-Za-z][A-Za-z0-9_]*` name; rejected without a lookup.
  invalidName,
}

/// Static policy functions (Java `JsEnvPolicy` parity).
class JsEnvPolicy {
  JsEnvPolicy._();

  /// Name of the variable that extends the allowlist (itself readable).
  static const String allowlistKey = 'JS_ENV_ALLOWLIST';

  /// Words that mark a `_`-separated name as a credential (Java `SECRET_WORDS`).
  static const Set<String> _secretWords = {
    'TOKEN', 'TOKENS', 'PAT', 'KEY', 'KEYS', 'SECRET', 'SECRETS', //
    'PASSWORD', 'PASSWORDS', 'PASSWD', 'PASS', 'CREDENTIAL', 'CREDENTIALS',
    'AUTH', 'AUTHORIZATION', 'LOGIN', 'PRIVATE', 'CERT', 'CERTIFICATE',
    'SIGNATURE', 'COOKIE', 'COOKIES', 'SESSION', 'BEARER', 'PASSPHRASE',
    'APIKEY',
  };

  static final RegExp _validName = RegExp(r'^[A-Za-z][A-Za-z0-9_]*$');
  static final RegExp _upperName = RegExp(r'^[A-Z][A-Z0-9_]*$');
  static final RegExp _separators = RegExp(r'[,\s]+');

  /// True when [name] looks like a secret. A null or blank name fails closed.
  static bool looksSecret(String? name) {
    if (name == null || name.trim().isEmpty) return true;
    final words = name.trim().toUpperCase().split('_');
    // Limits and counters that merely contain TOKEN(S) are configuration.
    if (words.contains('MAX') &&
        (words.contains('TOKENS') || words.contains('TOKEN'))) {
      return false;
    }
    if (words.contains('TOKEN') &&
        (words.contains('LIMIT') ||
            words.contains('LIMITS') ||
            words.contains('COUNT'))) {
      return false;
    }
    for (final word in words) {
      if (_secretWords.contains(word)) return true;
      if (word.endsWith('TOKEN') ||
          word.endsWith('SECRET') ||
          word.endsWith('PASSWORD') ||
          word.endsWith('APIKEY')) {
        return true;
      }
    }
    return false;
  }

  /// Built-in allowlist: every declared [PropertyNames] constant minus the
  /// secrets, plus [allowlistKey].
  static final Set<String> defaultAllowed = Set.unmodifiable({
    for (final name in PropertyNames.all)
      if (!looksSecret(name)) name,
    allowlistKey,
  });

  /// Names added through `JS_ENV_ALLOWLIST` (comma/space separated), upper
  /// cased, secrets dropped.
  static Set<String> projectAllowed(String? rawAllowlist) => {
        for (final name in _tokens(rawAllowlist))
          if (_upperName.hasMatch(name) && !looksSecret(name)) name,
      };

  /// Names from `JS_ENV_ALLOWLIST` rejected because they look like secrets.
  static Set<String> rejectedFromAllowlist(String? rawAllowlist) => {
        for (final name in _tokens(rawAllowlist))
          if (_upperName.hasMatch(name) && looksSecret(name)) name,
      };

  /// Decision for one [name] given the raw `JS_ENV_ALLOWLIST` value.
  static EnvDecision decide(String? name, String? rawProjectAllowlist) {
    if (name == null || !_validName.hasMatch(name)) {
      return EnvDecision.invalidName;
    }
    final upper = name.toUpperCase();
    if (looksSecret(upper)) return EnvDecision.secret;
    if (defaultAllowed.contains(upper) ||
        projectAllowed(rawProjectAllowlist).contains(upper)) {
      return EnvDecision.allowed;
    }
    return EnvDecision.notAllowlisted;
  }

  static Iterable<String> _tokens(String? raw) sync* {
    if (raw == null) return;
    for (final part in raw.split(_separators)) {
      final name = part.trim().toUpperCase();
      if (name.isNotEmpty) yield name;
    }
  }
}
"}

{"content":"/// `env_get` / `env_list` — read-only access to NON-SECRET configuration for
/// JS agents. Dart port of Java `com.github.istin.dmtools.env.EnvTools`.
///
/// The policy lives in [JsEnvPolicy]; this file only applies it. Both tools
/// answer with a JSON string. A refusal never contains the value.
library;

import 'dart:convert';

import '../../config/property_reader.dart';
import '../../env/js_env_policy.dart';
import '../../mcp/tool_definition.dart';
import '../../mcp/tool_param.dart';

/// Returns the `env` integration tool definitions.
List<ToolDefinition> envTools() => const [
      ToolDefinition(
        name: 'env_get',
        description:
            'Read one non-secret configuration value (for example ADO_PROJECT, '
            'DEFAULT_TRACKER, JIRA_BASE_PATH). Credentials (names containing '
            'TOKEN, KEY, SECRET, PASSWORD, PAT, AUTH, ...) are never returned. '
            'Names outside the built-in list can be allowed with '
            'JS_ENV_ALLOWLIST=NAME1,NAME2. Returns {"name":..,"value":..} or '
            '{"name":..,"error":..}; value is null when the variable is unset.',
        integration: 'env',
        category: 'configuration',
        params: [
          ToolParam(
            name: 'name',
            description: 'Configuration variable name',
            example: 'ADO_PROJECT',
          ),
        ],
      ),
      ToolDefinition(
        name: 'env_list',
        description:
            'List the configuration names env_get will answer for: the built-in '
            'non-secret names plus those added through JS_ENV_ALLOWLIST. Names '
            'only, never values.',
        integration: 'env',
        category: 'configuration',
      ),
    ];

/// Reads configuration values for the `env_*` tools.
///
/// [lookup] supplies values; production uses [PropertyReader.getValue], tests
/// inject a map-backed function. The lookup is called for [JsEnvPolicy.allowlistKey]
/// and for allowed names only — never for secrets or invalid names.
class EnvTools {
  /// Value source (Java `EnvTools` test seam).
  final String? Function(String key) lookup;

  /// Creates the tools over [lookup].
  EnvTools({String? Function(String key)? lookup})
      : lookup = lookup ?? ((key) => PropertyReader().getValue(key));

  /// Sync handlers keyed by tool name, JSON-string results.
  Map<String, String Function(Map<String, dynamic> args)> get handlers => {
        'env_get': (args) => envGet(args['name']?.toString()),
        'env_list': (_) => envList(),
      };

  /// `env_get {name}` — see the tool description for the contract.
  String envGet(String? name) {
    final decision = JsEnvPolicy.decide(name, lookup(JsEnvPolicy.allowlistKey));
    final out = <String, dynamic>{'name': name};
    switch (decision) {
      case EnvDecision.allowed:
        final value = lookup(name!.toUpperCase());
        out['value'] = (value == null || value.isEmpty) ? null : value;
      case EnvDecision.secret:
        out['error'] = 'not readable: the name looks like a credential';
      case EnvDecision.notAllowlisted:
        out['error'] =
            'not allowed: add it to JS_ENV_ALLOWLIST to make it readable';
      case EnvDecision.invalidName:
        out['error'] =
            'invalid name: expected letters, digits and underscores';
    }
    return jsonEncode(out);
  }

  /// `env_list {}` — names only, plus `ignoredSecretLikeNames` when the
  /// allowlist contains credential-looking entries.
  String envList() {
    final raw = lookup(JsEnvPolicy.allowlistKey);
    final all = {
      ...JsEnvPolicy.defaultAllowed,
      ...JsEnvPolicy.projectAllowed(raw),
    }.toList()
      ..sort();
    final out = <String, dynamic>{'names': all};
    final rejected = JsEnvPolicy.rejectedFromAllowlist(raw).toList()..sort();
    if (rejected.isNotEmpty) out['ignoredSecretLikeNames'] = rejected;
    return jsonEncode(out);
  }
}
